142	PlatformId ArmPlatformIdFromMainId(uint32_t implementer, uint32_t part_number) {
143	  if (implementer == 0x41) {
144	    // This means the core is ARM IP. Different SoCs may use the same IP.
145	    switch (part_number) {
146	      case 0xd0c:
147	        return PlatformId::kArmNeoverseN1;
148	      case 0xd49:
149	        return PlatformId::kArmNeoverseN2;
150	      case 0xd4f:
151	        return PlatformId::kArmNeoverseV2;
152	      case 0xd8e:
153	        return PlatformId::kArmNeoverseN3;
154	      default:
155	        LOG_ERROR("Unknown ARM part number: ", HexStr(part_number));
156	        return PlatformId::kUndefined;
157	    }
158	  } else if (implementer == 0xc0) {
159	    // Ampere Computing
160	    if (part_number == 0xac3) {
161	      return PlatformId::kAmpereOne;
162	    }
163	    LOG_ERROR("Unknown Ampere part number: ", HexStr(part_number));
164	    return PlatformId::kUndefined;
165	  } else if (implementer == 0x48) {
166	    return PlatformId::kArmNeoverseN1;
167	  }
168	
169	  LOG_ERROR("Unknown implementer: ", HexStr(implementer));
